describe('File Upload Cancellation', () => {
    beforeEach(() => {
        cy.visit('/upload'); // Replace with the actual URL of the upload page
    });

    it('should successfully cancel an in-progress upload', () => {
        const fileName = 'test-file.txt'; // Replace with an actual file name
        cy.fixture(fileName).as('fileToUpload');

        cy.get('input[type="file"]').attachFile(this.fileToUpload);
        cy.get('.upload-progress').should('be.visible');

        cy.get('.cancel-upload-button').click();
        cy.get('.upload-progress').should('not.exist');
        cy.get('.upload-status').should('contain', 'Upload cancelled');
    });

    it('should not allow cancellation if no upload is in progress', () => {
        cy.get('.cancel-upload-button').should('be.disabled');
        cy.get('.upload-status').should('not.exist');
    });
});
